import{_ as a,o as s,c as i,a5 as o}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"Internacionalización y accesibilidad","description":"","frontmatter":{"title":"Internacionalización y accesibilidad","docId":"developer.i18n-accessibility","translationKey":"developer.i18n-accessibility","locale":"es","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2c74fcefd1d28353b1135c547b2e3e6ae852af8b683350011732d10c364f9323","translationRevision":"7e5396d6a3fe88516053b2d31e9f75b69b915a96a9e89bd6cbfc6b87ef8f8db8","order":120},"headers":[],"relativePath":"es/developer/i18n-accessibility.md","filePath":"es/developer/i18n-accessibility.md","lastUpdated":1794611623000}'),t={name:"es/developer/i18n-accessibility.md"};function n(c,e,l,r,d,p){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="internationalization-and-accessibility" tabindex="-1">Internacionalización y accesibilidad <a class="header-anchor" href="#internationalization-and-accessibility" aria-label="Permalink to &quot;Internacionalización y accesibilidad {#internationalization-and-accessibility}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Añade pantallas comprensibles en los idiomas admitidos y utilizables con teclado, tacto y tecnologías de asistencia. Lee las <a href="./frontend.html">capas frontend</a> y usa la interfaz compartida. Los idiomas de la aplicación y las ediciones publicadas de esta documentación son sistemas distintos.</p><h2 id="add-localized-content" tabindex="-1">Añadir contenido localizado <a class="header-anchor" href="#add-localized-content" aria-label="Permalink to &quot;Añadir contenido localizado {#add-localized-content}&quot;">​</a></h2><p>El catálogo está en <code>src/web/shared/i18n/</code>. Inglés es la referencia tipada; los demás catálogos compatibles se cargan bajo demanda. <code>activateLocale</code> carga los mensajes y actualiza <code>document.documentElement.lang</code>. Guarda la preferencia mediante el almacén existente, sin crear otra clave de almacenamiento local.</p><ol><li>Añade la clave semántica al catálogo inglés y a sus módulos equivalentes en los otros idiomas.</li><li>Conserva identificadores API, rutas de eventos y recursos guardados; traduce sus etiquetas visibles.</li><li>Usa interpolación para textos variables y las utilidades compartidas de formato.</li><li>Para descriptores de plugins, emplea <code>{default,i18key}</code> y los catálogos integrados por el host. Nunca interpreta como HTML los textos traducidos o proporcionados por plugins.</li></ol><h2 id="preserve-control-semantics" tabindex="-1">Conservar la semántica de los controles <a class="header-anchor" href="#preserve-control-semantics" aria-label="Permalink to &quot;Conservar la semántica de los controles {#preserve-control-semantics}&quot;">​</a></h2><p>Prefiere <code>BaseTextField</code>, <code>BaseFormRow</code>, <code>BaseDialog</code>, pestañas y componentes de estado. Un texto de ejemplo no reemplaza una etiqueta accesible. Los botones de icono necesitan nombre localizado. La validación debe identificar el campo y exponer su invalidez; el color no basta para comunicar errores. Conserva retorno del foco, Escape, selección mediante teclado y contornos visibles.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalogs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BaseDialog</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span></code></pre></div><p>En revisión manual, recorre todo con Tab, abre/cierra el diálogo, cambia idioma mientras está abierto y repite con ancho estrecho. Las acciones de estado visibles al pasar el cursor también deben aparecer con foco y estar disponibles al tocar.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>El tipado y las comprobaciones de catálogos detectan claves ausentes; los controles compartidos implementan teclado y ARIA. Esto no certifica automáticamente la accesibilidad de cada pantalla compuesta. Rankings sigue oculto aunque tenga traducciones.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si aparece texto sin traducir, revisa carga diferida y nombre exacto de la clave antes de añadir inglés dentro del componente. Si desaparece el foco, inspecciona el control receptor de atributos y el destino de retorno. La <a href="https://github.com/nglmercer/TikTools-app/blob/remake/src/web/shared/i18n/i18n.ts" target="_blank" rel="noreferrer">implementación i18n</a> y las pruebas definen el comportamiento actual; <a href="./components/">componentes</a> presenta las entradas compartidas.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Detección: <code>tiktok-live-locale</code> guardado → <code>navigator.languages</code> → inglés. <code>normalizeLocale</code> normaliza regiones y <code>jp</code> → <code>ja</code>. Códigos/regiones: <code>en/en-US</code>, <code>es/es-ES</code>, <code>pt/pt-BR</code>, <code>fr/fr-FR</code>, <code>zh/zh-CN</code>, <code>ja/ja-JP</code>; usa formatCount/formatDate de <code>intl.ts</code>. <code>activateLocale</code> carga mensajes/lang; <code>useLocaleStore().setLocale</code> además persiste y prepara preferencias de mejor esfuerzo. Usa store para ajustes. Inglés es fallback; zh/ja cargan módulos de mensajes host. Para nuevo idioma actualiza supported-locales, loaders, catálogos/host, regiones, tests de preferencias y claves/placeholders/plurales/compilación, y rutas docs/sitio. Conserva IDs/API y parámetros.</p><p>Usa tokens de espacio/tipo/control/foco/capas. Puntero grueso o ancho menor de 700px eleva controles a 44px; navegación cambia bajo 900px y filas bajo 600px, independientemente. Movimiento reducido deja duraciones a cero. Prueba tacto también en escritorio ancho. La app es oscura globalmente; override claro solo aplica a JSON.</p><p>Teclado: pestañas usan flechas/Home/End y selección automática; selects flechas/Home/End/Enter y Escape cancela; menús devuelven foco al disparador. Diálogos usan showModal nativo, pero <code>closable=false</code> bloquea Escape y cerrar desmonta contenido. Conserva borradores en propietario y verifica foco inicial/retorno. Botones icono requieren <code>label</code>; <code>hint</code>/tooltip explica, no nombra. Tooltip espera 500ms en hover/foco, cierra con Escape y respeta top layer del diálogo. Revisa flujos reales de teclado/asistencia; unit tests no certifican pantalla completa.</p>`,18)])])}const m=a(t,[["render",n]]);export{u as __pageData,m as default};
